const getRootElementFontSize = () =>
  parseFloat(getComputedStyle(document.documentElement).fontSize)

const handleScroll = () => {
  const element = floatingBarRef.value
  if (!element) return

  const { height, top } = element.getBoundingClientRect()
  isSticky.value =
    height + top + getRootElementFontSize() !== window.innerHeight
}

const throttledHandleScroll = useThrottleFn(handleScroll, 30)

onMounted(() => {
  observer.value = new ResizeObserver(throttledHandleScroll)

  const page = document.getElementById(PAGE_ID)
  if (page) observer.value.observe(page)

  window.addEventListener('scroll', throttledHandleScroll)
  handleScroll()
})

onBeforeUnmount(() => {
  window.removeEventListener('scroll', throttledHandleScroll)
  observer.value?.disconnect()
})

